import{_ as s,o as t,a as e,b as c}from"./app.UgfkfLuP.js";const n="/ascendc.github.io/assets/datacopy_address_overlap_sync_diagram.GPkouKmg.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/c_api/data_move_guide/overview/overview"},{"text":"总体约束说明","link":"/api/SIMD-API/c_api/data_move_guide/overview/overall_constraints"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/overview/overall_constraints.md","filePath":"api/SIMD-API/c_api/data_move_guide/overview/overall_constraints.md","outlineHeaders":[{"level":2,"title":"地址对齐约束","slug":"地址对齐约束","link":"#地址对齐约束"},{"level":2,"title":"参数单位","slug":"参数单位","link":"#参数单位"},{"level":2,"title":"搬运量与存储边界","slug":"搬运量与存储边界","link":"#搬运量与存储边界"},{"level":2,"title":"执行范围","slug":"执行范围","link":"#执行范围"},{"level":2,"title":"多指令同步","slug":"多指令同步","link":"#多指令同步"},{"level":2,"title":"地址重叠","slug":"地址重叠","link":"#地址重叠"},{"level":2,"title":"初始化与配置状态","slug":"初始化与配置状态","link":"#初始化与配置状态"}],"lastUpdated":1790563388000}'),d={name:"api/SIMD-API/c_api/data_move_guide/overview/overall_constraints.md"};function p(l,a,i,_,o,r){return t(),e("div",null,[...a[0]||(a[0]=[c('<div><article class="markdown-body"><h1>总体约束说明</h1><p>数据搬运接口共享地址对齐、存储容量、参数单位和同步等通用规则。调用前应先完成本节检查；具体接口文档给出的要求更严格时，以具体接口为准。</p><h2 id="地址对齐约束">地址对齐约束<a class="header-anchor" href="#地址对齐约束">​</a></h2><p>NPU架构版本3510各存储单元的架构基线对齐如下表所示。</p><p><strong>表1</strong> 存储单元地址对齐要求</p><table><thead><tr><th>存储单元</th><th>地址空间或对象</th><th>架构基线对齐</th><th>说明</th></tr></thead><tbody><tr><td>Global Memory</td><td><code>__gm__</code></td><td>1字节</td><td>接口仍可能按数据类型要求2字节或4字节对齐。</td></tr><tr><td>UB</td><td><code>__ubuf__</code></td><td>32字节</td><td>普通DMA搬运通常要求32字节对齐；NDDMA和部分Reg接口的要求不同。</td></tr><tr><td>L1 Buffer</td><td><code>__cbuf__</code></td><td>32字节</td><td>与DataBlock大小一致。</td></tr><tr><td>L0A/L0B Buffer</td><td><code>__ca__</code>/<code>__cb__</code></td><td>512字节</td><td>二维、三维矩阵搬运通常以完整分形为粒度。</td></tr><tr><td>L0C Buffer</td><td><code>__cc__</code></td><td>64字节</td><td>L0C搬出接口的源地址要求。</td></tr><tr><td>BiasTable Buffer</td><td><code>uint64_t</code>目的地址</td><td>64字节</td><td>容量上限为4KB。</td></tr><tr><td>Fixpipe Buffer量化参数空间</td><td><code>__fbuf__</code></td><td>128字节</td><td>容量上限为4KB。</td></tr><tr><td>Fixpipe Buffer ReLU参数空间</td><td><code>__fbuf__</code></td><td>64字节</td><td>容量上限为2KB。</td></tr></tbody></table><p>架构基线不等于所有原型的最终约束。例如NDDMA的目的UB地址允许1字节对齐，Reg加载和存储的部分元素或掩码模式可按数据类型、8字节或16字节对齐。地址不满足普通接口要求时，应选择对应的非对齐接口，不能通过向前取整地址或扩大访问范围读写未分配空间。</p><h2 id="参数单位">参数单位<a class="header-anchor" href="#参数单位">​</a></h2><p>数据搬运参数常见以下单位：</p><ul><li><code>size</code>通常以字节为单位，但<code>asc_copy_ub2ub</code>、<code>asc_copy_ub2l1</code>、<code>asc_copy_l12bt</code>和<code>asc_copy_l12fb</code>等接口会按32字节粒度处理，不对齐部分可能被向下截断。</li><li><code>burst_len</code>、<code>len_burst</code>可能以字节、32字节DataBlock、64字节或512字节分形为单位。</li><li><code>src_stride</code>、<code>dst_stride</code>可能表示相邻数据块<strong>起始地址之间</strong>的距离；<code>src_gap</code>、<code>dst_gap</code>通常表示前一数据块<strong>结束地址到下一数据块起始地址</strong>的间隔。</li><li>L1到L0A/L0B二维搬运中的行列起始位置和步长分别可能以16个元素、32字节或512字节分形为单位。</li><li>NDDMA各维循环大小、源步长、目的步长和Padding数量以元素个数为单位。</li><li>Reg接口的偏移可能以元素、字节或DataBlock为单位。</li></ul><p>同名参数在不同接口中的单位不一定相同。计算源、目的地址跨度时，应先按接口文档把所有参数换算为字节，再检查对齐和边界。</p><h2 id="搬运量与存储边界">搬运量与存储边界<a class="header-anchor" href="#搬运量与存储边界">​</a></h2><p><a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/architecture_spec/npu_arch_3510.html">NPU架构版本3510硬件规格</a>中的主要片上存储容量如下：</p><table><thead><tr><th>存储单元</th><th>容量上限</th></tr></thead><tbody><tr><td>UB</td><td>256KB；实际可用空间还会扣除SIMD VF栈、预留空间以及SIMD+SIMT混编时的Data Cache。</td></tr><tr><td>L1 Buffer</td><td>512KB</td></tr><tr><td>L0A/L0B Buffer</td><td>各64KB</td></tr><tr><td>L0C Buffer</td><td>256KB</td></tr><tr><td>L0A_MX/L0B_MX Buffer</td><td>各4KB</td></tr><tr><td>BiasTable Buffer</td><td>4KB</td></tr><tr><td>Fixpipe Buffer</td><td>量化参数空间4KB，ReLU参数空间2KB</td></tr></tbody></table><p>源、目的起始地址加上实际访问跨度均不得超过已分配范围。高维切分模式需要把最后一个数据块的起始偏移与块长相加；GM与UB之间的非32字节有效长度需要计入UB一侧的32字节补齐访问，即使使用普通接口也不例外；左右Padding也需要计入实际跨度；随路格式或类型转换需要按目的数据类型和目的布局重新计算空间；矩阵搬运还需要计入边界分形中的填充元素。</p><h2 id="执行范围">执行范围<a class="header-anchor" href="#执行范围">​</a></h2><ul><li>矩阵数据搬运接口通常仅在AIC生效，矢量数据搬运接口通常仅在AIV生效；在不支持的执行核调用时，部分接口会直接返回而不执行搬运。</li><li>Reg加载、存储接口仅在AIV的Vector Function（<code>__simd_vf__</code>标记的函数）内使用。</li><li>L1到UB接口在AIC发射，并通过<code>sub_blockid</code>选择目的AIV；AIC与AIV之间共享数据时还需要满足相应核间同步要求。</li><li>通过宏区分AIC和AIV代码路径时，应保证接口只在其支持的分支执行。</li></ul><h2 id="多指令同步">多指令同步<a class="header-anchor" href="#多指令同步">​</a></h2><p>搬运指令由Scalar发射后在对应硬件流水异步执行，不能仅根据源码书写顺序推断不同流水之间的完成顺序。同步分为以下两类：</p><ul><li><strong>同一流水同步：</strong> 多条PIPE_MTE2或PIPE_MTE3指令的目的地址存在重叠时，使用<a href="../../sync/intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a>等待前序搬运完成，再发射会覆盖同一区域的后序搬运。</li><li><strong>不同流水同步：</strong> 生产者和消费者位于不同流水时，使用<a href="../../sync/intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>和<a href="../../sync/intra_core_sync/asc_sync_wait.html">asc_sync_wait</a>建立事件依赖，或按接口文档选择对应的易用同步接口。</li></ul><p>图1左侧表示两次UB到GM搬运的目的GM范围重叠，图1右侧表示两次GM到UB搬运的目的UB范围重叠。两种场景都需要在同一搬运流水内等待前一条指令完成。</p><p><strong>图1</strong> 搬运目的地址重叠</p><p><img src="'+n+`" alt="搬运目的地址重叠" title="搬运目的地址重叠"></p><p>以下代码展示PIPE_MTE2上两次GM到UB搬运的目的区域重叠时的同步方式：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">ub0</span><span class="p">,</span><span class="w"> </span><span class="n">gm0</span><span class="p">,</span><span class="w"> </span><span class="n">size0</span><span class="p">);</span>
<span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">);</span>
<span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">ub1</span><span class="p">,</span><span class="w"> </span><span class="n">gm1</span><span class="p">,</span><span class="w"> </span><span class="n">size1</span><span class="p">);</span>
</code></pre></div><p>如果GM到UB搬运的结果随后由PIPE_V读取，则需要建立PIPE_MTE2到PIPE_V的依赖：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">ub0</span><span class="p">,</span><span class="w"> </span><span class="n">gm0</span><span class="p">,</span><span class="w"> </span><span class="n">size0</span><span class="p">);</span>
<span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="c1">// 在此调用读取ub0的PIPE_V接口。</span>
</code></pre></div><p>事件ID由同一对源、目的流水共享，<code>asc_sync_notify</code>和<code>asc_sync_wait</code>的流水与事件参数必须完全一致。可用流水组合和事件资源请参见<a href="../../sync/intra_core_sync/intra_core_sync_overview.html">核内同步</a>。</p><h2 id="地址重叠">地址重叠<a class="header-anchor" href="#地址重叠">​</a></h2><p>源、目的有效搬运区域是否允许重叠由具体接口决定。NPU架构版本3510的UB内部复制要求实际参与搬运的源、目的DataBlock互不重叠，即使两段地址的整体跨度可以交叠，也不能把<code>asc_copy_ub2ub</code>当作支持重叠区域的<code>memmove</code>。Reg指令访问重叠UB区域并存在读写冲突时，按对应接口要求使用<a href="../../reg_compute/reg_sync/asc_mem_bar.html">asc_mem_bar</a>。</p><h2 id="初始化与配置状态">初始化与配置状态<a class="header-anchor" href="#初始化与配置状态">​</a></h2><ul><li>Kernel入口建议先调用<a href="../../utils/sys_init/asc_init.html">asc_init</a>，清理可能由前序任务保留的控制状态。</li><li>Padding、循环、Nz格式转换、量化、激活和矩阵三维搬运等配置接口会影响后续搬运指令。复用配置前，应确认所有相关字段均已按当前任务更新。</li><li>多核可能读取同一块GM且该数据可能被其他核更新时，应在NDDMA前按<a href="../../vector_datamove/asc_ndim_copy_dci.html">asc_ndim_copy_dci</a>要求刷新NDDMA DataCache。</li></ul><p>存储空间和C API通用规则请参见<a href="../../general_description_and_constraints.html">通用说明和约束</a>。</p></article></div>`,1)])])}const g=s(d,[["render",p]]);export{u as __pageData,g as default};
